begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(body_private.grant_valid_at('2028-02-15 00:00:00Z','2028-02-29 00:00:00Z',null,'2028-02-28 23:59:59.999999Z'),'one microsecond before expiration');
select ok(not body_private.grant_valid_at('2028-02-15 00:00:00Z','2028-02-29 00:00:00Z',null,'2028-02-29 00:00:00Z'),'exact expiration denies');
select ok(not body_private.grant_valid_at('2028-02-15 00:00:00Z','2028-02-29 00:00:00Z',null,'2028-02-29 00:00:00.000001Z'),'after expiration denies');
select ok(not body_private.grant_valid_at('2028-02-15 00:00:00Z',null,'2028-02-16 00:00:00Z','2028-02-17 00:00:00Z'),'revocation defeats perpetual grant');
select ok(not body_private.grant_valid_at('2028-02-15 00:00:00Z',null,null,'2028-02-14 00:00:00Z'),'future grant denies');
set local timezone='America/New_York';
select is(extract(epoch from (('2026-03-01 12:00:00-05'::timestamptz+interval '336 hours')-'2026-03-01 12:00:00-05'::timestamptz))::integer,1209600,'DST does not shorten fourteen consecutive days');
set local timezone='UTC';
insert into auth.users(id,email_confirmed_at) values(md5('ent_a')::uuid,clock_timestamp()),(md5('ent_b')::uuid,clock_timestamp());
insert into auth.users(id) values(md5('ent_unverified')::uuid);
insert into profiles(id,display_name) values(md5('ent_a')::uuid,'A'),(md5('ent_b')::uuid,'B');
insert into account_preferences(owner_id) values(md5('ent_a')::uuid),(md5('ent_b')::uuid);
select set_config('request.jwt.claims',json_build_object('sub',md5('ent_a')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select lives_ok('select activate_account_trial()','verified existing account activates');
select lives_ok('select activate_account_trial()','activation retries safely');
select is(account_access()->>'allowed','true','trial authorizes');
select is(account_access()->>'source','trial','source is trial');
select is((account_access()->>'trialExpiresAt')::timestamptz-(account_access()->>'trialActivatedAt')::timestamptz,interval '336 hours','exact consecutive trial duration');
select set_config('e.exp',account_access()->>'trialExpiresAt',true);
select lives_ok('select activate_account_trial()','refresh/login does not reset');
select is(account_access()->>'trialExpiresAt',current_setting('e.exp'),'same permanent expiration');
select set_config('e.w',start_ad_hoc_workout()::text,true);
select set_config('e.selection',edit_workout(current_setting('e.w')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select set_config('e.selection2',edit_workout(current_setting('e.w')::uuid,'add',(select id from exercises where slug='standing_dumbbell_curl'))::text,true);
select set_config('e.set',(select id::text from workout_sets where workout_exercise_id=current_setting('e.selection')::uuid order by position limit 1),true);
select set_config('e.set_request',gen_random_uuid()::text,true);
select lives_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,current_setting('e.set')::uuid,'save',0,current_setting('e.set_request')::uuid,8,60,'working','external',true)$$,'set mutation and immutable receipt commit together');
select throws_ok('update workout_set_receipts set payload=payload','42501',null,'set receipts cannot be rewritten');
select throws_ok('delete from workout_set_receipts','42501',null,'set receipts cannot be deleted to reuse UUIDs');
select set_config('e.item',gen_random_uuid()::text,true);
select set_config('e.req',gen_random_uuid()::text,true);
select lives_ok($$select record_workout_cardio(current_setting('e.w')::uuid,current_setting('e.item')::uuid,'add',0,'bike',null,current_setting('e.req')::uuid)$$,'authorized cardio');
select throws_ok('select * from body_private.account_trials','42501',null,'private trials inaccessible even to owner');
select throws_ok('select * from body_private.access_grants','42501',null,'private provenance inaccessible');
select throws_ok($$insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from) values(auth.uid(),'lifetime','forged','forged',clock_timestamp())$$,'42501',null,'ordinary owner cannot mint lifetime access');
select throws_ok($$insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from) values(md5('ent_b')::uuid,'lifetime','forged','foreign',clock_timestamp())$$,'42501',null,'ordinary owner cannot mint foreign access');
select throws_ok($$update body_private.account_trials set expires_at=expires_at+interval '14 days'$$,'42501',null,'trial expiration cannot be edited');
select throws_ok('delete from body_private.account_trials','42501',null,'trial history cannot be deleted to restart');
select throws_ok('update body_private.access_grants set revoked_at=clock_timestamp()','42501',null,'ordinary owner cannot revoke grants');
select ok(not(account_access() ? 'source_reference'),'summary excludes grant provenance');

select throws_ok($$update workout_sessions set access_continuation_until=clock_timestamp()+interval '1 year'$$,'42501',null,'client cannot extend continuation');
select throws_ok($$select activate_account_trial(clock_timestamp())$$,'42883',null,'no client activation clock argument');
select throws_ok($$select account_access(gen_random_uuid())$$,'42501',null,'foreign/missing session cannot supply continuation');
reset role;
select is((select count(*)::int from body_private.account_trials where owner_id=md5('ent_a')::uuid),1,'exactly one activation fact');
select is((select count(*)::int from body_private.access_grants where owner_id=md5('ent_a')::uuid),1,'exactly one grant');
-- Protected fixtures control authoritative expiration; no production clock override.
update body_private.access_grants set valid_from=clock_timestamp()-interval '15 days',expires_at=clock_timestamp()-interval '1 minute' where owner_id=md5('ent_a')::uuid;
update public.workout_sessions set access_authorized_at=clock_timestamp()-interval '2 minutes',access_continuation_until=clock_timestamp()+interval '239 minutes' where id=current_setting('e.w')::uuid;
set local role authenticated;
select is(account_access()->>'allowed','false','expired trial denies account access');
select is(account_access(current_setting('e.w')::uuid)->>'continuationAllowed','true','same server-authorized session continues');
reset role;
update workout_sessions set last_activity_at=clock_timestamp()-interval '13 hours' where id=current_setting('e.w')::uuid;
set local role authenticated;
select is(account_access(current_setting('e.w')::uuid)->>'continuationAllowed','false','existing hard expiry is stricter than entitlement grace');
reset role;
update workout_sessions set last_activity_at=clock_timestamp() where id=current_setting('e.w')::uuid;
set local role authenticated;

select lives_ok($$select record_workout_cardio(current_setting('e.w')::uuid,current_setting('e.item')::uuid,'save',1,'bike',600,gen_random_uuid())$$,'cardio works during continuation');
select lives_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,gen_random_uuid(),'add',null,gen_random_uuid())$$,'same-session new set during continuation');
select set_config('e.latest_set_request',gen_random_uuid()::text,true);
select lives_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,current_setting('e.set')::uuid,'save',1,current_setting('e.latest_set_request')::uuid,9,65,'working','external',true)$$,'another device can save a newer revision during continuation');
select set_config('e.group',gen_random_uuid()::text,true);
select lives_ok($$select change_workout_group(current_setting('e.w')::uuid,current_setting('e.group')::uuid,'create',0,jsonb_build_array(jsonb_build_object('type','selection','id',current_setting('e.selection')),jsonb_build_object('type','selection','id',current_setting('e.selection2'))),gen_random_uuid())$$,'same-session Superset during continuation');

-- Existing start RPC resumes an existing active workout by design; direct new INSERT must deny.
select throws_ok($$insert into workout_sessions(owner_id,name) values(auth.uid(),'bypass')$$,'P7701',null,'new session direct DML denied');
select throws_ok($$insert into favorite_workouts(owner_id,name,source_type,source_version_id,source_day_id,save_request) select auth.uid(),'bypass','program_day',v.id,(d->>'id')::uuid,gen_random_uuid() from program_versions v cross join lateral jsonb_array_elements(v.definition->'days')d where not(d->>'is_rest_day')::boolean limit 1$$,'P7701',null,'new Favorite direct DML denied');
select lives_ok('select activate_account_trial()','expired activation retry returns original facts');
select is(account_access()->>'allowed','false','expired trial never restarts');
select lives_ok('select * from profiles where id=auth.uid()','profile reads survive');
select lives_ok('select * from workout_sessions','workout history reads survive');
select lives_ok($$update account_preferences set display_weight_unit='kg' where owner_id=auth.uid()$$,'account preferences editable');
reset role;
select is((select count(*)::int from body_private.account_trials where owner_id=md5('ent_a')::uuid),1,'no second expired activation');
-- Grant precedence, future grants and revocation use protected local fixtures only.
insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from,expires_at)
values(md5('ent_a')::uuid,'subscription','fixture','sub',clock_timestamp()-interval '1 day',clock_timestamp()+interval '1 day');
set local role authenticated;
select is(account_access()->>'source','subscription','active subscription overrides expired trial');
reset role;
update body_private.access_grants set revoked_at=clock_timestamp() where source='fixture';
insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from,expires_at)
values(md5('ent_a')::uuid,'promotion','fixture','promo',clock_timestamp()-interval '1 day',clock_timestamp()+interval '2 days');
set local role authenticated;
select is(account_access()->>'source','promotion','valid promotion overrides revoked subscription');
reset role;
insert into body_private.access_grants(owner_id,kind,source,source_reference,valid_from)
values(md5('ent_a')::uuid,'lifetime','fixture','life',clock_timestamp()-interval '1 day');
set local role authenticated;
select is(account_access()->>'source','lifetime','perpetual grant wins relevant expiration');
select is(account_access()->>'expiresAt',null,'lifetime has no fake distant expiration');
reset role;
update body_private.access_grants set revoked_at=clock_timestamp() where source='fixture';
update public.workout_sessions set access_continuation_until=clock_timestamp()-interval '1 second' where id=current_setting('e.w')::uuid;
set local role authenticated;
select is(account_access(current_setting('e.w')::uuid)->>'continuationAllowed','false','fixed continuation deadline expires');
select lives_ok($$select record_workout_cardio(current_setting('e.w')::uuid,current_setting('e.item')::uuid,'add',0,'bike',null,current_setting('e.req')::uuid)$$,'identical committed receipt recovers after deadline');
select throws_ok($$select record_workout_cardio(current_setting('e.w')::uuid,current_setting('e.item')::uuid,'add',0,'treadmill',null,current_setting('e.req')::uuid)$$,'23514',null,'changed receipt payload rejected after deadline');
select throws_ok($$select record_workout_cardio(current_setting('e.w')::uuid,current_setting('e.item')::uuid,'save',2,'bike',900,gen_random_uuid())$$,'P7701',null,'new cardio denied after continuation');
select lives_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,current_setting('e.set')::uuid,'save',0,current_setting('e.set_request')::uuid,8,60,'working','external',true)$$,'old committed set receipt recovers after grace and a newer device edit');
select is((select actual_weight_kg from workout_sets where id=current_setting('e.set')::uuid),65::numeric,'receipt recovery never overwrites newer saved performance');
select is((select revision from workout_sets where id=current_setting('e.set')::uuid),2,'receipt recovery creates no revision or activity');
select throws_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,current_setting('e.set')::uuid,'save',0,current_setting('e.set_request')::uuid,99,60,'working','external',true)$$,'23514',null,'changed set payload with committed UUID rejected after grace');
select throws_ok($$insert into workout_set_receipts(mutation_id,workout_session_id,workout_exercise_id,set_id,payload) select gen_random_uuid(),workout_session_id,workout_exercise_id,set_id,payload from workout_set_receipts limit 1$$,'42501',null,'direct receipt forgery cannot impersonate a committed mutation');
select throws_ok($$select * from log_workout_set(current_setting('e.selection')::uuid,gen_random_uuid(),'add',null,gen_random_uuid())$$,'P7701',null,'new set denied after continuation');
select throws_ok($$select edit_workout(current_setting('e.w')::uuid,'add',(select id from exercises where slug='barbell_back_squat'))$$,'P7701',null,'new movement selection denied after continuation');
select throws_ok($$insert into workout_movements(owner_id,workout_session_id,position,suggested_pattern_id,suggested_muscle_id,suggested_type,suggested_title,movement_nonce) select auth.uid(),current_setting('e.w')::uuid,99,ep.movement_pattern_id,em.muscle_group_id,e.exercise_type,'Test',gen_random_uuid() from exercises e join exercise_movement_patterns ep on ep.exercise_id=e.id and ep.is_primary join exercise_muscles em on em.exercise_id=e.id and em.muscle_role='primary' where e.slug='barbell_back_squat' limit 1$$,'P7701',null,'direct movement evidence denied after continuation');
select throws_ok($$select change_workout_group(current_setting('e.w')::uuid,current_setting('e.group')::uuid,'edit',1,jsonb_build_array(jsonb_build_object('type','selection','id',current_setting('e.selection2')),jsonb_build_object('type','selection','id',current_setting('e.selection'))),gen_random_uuid())$$,'P7701',null,'new Superset denied after continuation');
select throws_ok($$select end_workout(current_setting('e.w')::uuid,'completed')$$,'P7701',null,'cannot invent completion after continuation');
select is((select status from workout_sessions where id=current_setting('e.w')::uuid),'in_progress','access expiration never silently closes workout');
select lives_ok($$select end_workout(current_setting('e.w')::uuid,'abandoned')$$,'explicit abandonment remains safe cleanup');
reset role;
update body_private.access_grants set revoked_at=null where source='fixture' and kind='lifetime';
set local role authenticated;
select is(account_access()->>'allowed','true','restored grant restores account authority');
select throws_ok($$select edit_workout(current_setting('e.w')::uuid,'add',(select id from exercises where slug='barbell_back_squat'))$$,'23514',null,'restored entitlement never reopens terminal session');

select set_config('request.jwt.claims',json_build_object('sub',md5('ent_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::integer from workout_set_receipts),0,'foreign set receipt payloads remain owner-private');
select throws_ok($$select account_access(current_setting('e.w')::uuid)$$,'42501',null,'foreign continuation denied');
select set_config('request.jwt.claims',json_build_object('sub',md5('ent_unverified')::uuid,'role','authenticated')::text,true);
select throws_ok('select activate_account_trial()','42501',null,'unverified account cannot start clock');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',md5('ent_b')::uuid,'role','authenticated')::text,true);
set local role authenticated;
select set_config('e.finish',start_ad_hoc_workout()::text,true);
select set_config('e.version',(select id::text from program_versions limit 1),true);
select set_config('e.day',(select d->>'id' from program_versions v cross join lateral jsonb_array_elements(v.definition->'days')d where v.id=current_setting('e.version')::uuid and not(d->>'is_rest_day')::boolean limit 1),true);
select set_config('e.favorite',save_favorite_workout('program_day',current_setting('e.version')::uuid,current_setting('e.day')::uuid,'Kept Favorite',gen_random_uuid())::text,true);

reset role;
update body_private.access_grants set valid_from=clock_timestamp()-interval '15 days',expires_at=clock_timestamp()-interval '1 minute' where owner_id=md5('ent_b')::uuid;
update workout_sessions set access_authorized_at=clock_timestamp()-interval '2 minutes',access_continuation_until=clock_timestamp()+interval '3 hours' where id=current_setting('e.finish')::uuid;
set local role authenticated;
select lives_ok($$select end_workout(current_setting('e.finish')::uuid,'completed')$$,'explicit Finish works during valid continuation');
select throws_ok('select start_ad_hoc_workout()','P7701',null,'independent start RPC denied after expiration');
select throws_ok($$select start_favorite_workout(current_setting('e.favorite')::uuid,gen_random_uuid())$$,'P7701',null,'Favorite start RPC denied after expiration');
select throws_ok($$select start_program_workout(current_setting('e.version')::uuid,1,gen_random_uuid())$$,'P7701',null,'program workout start RPC denied after expiration');
select throws_ok($$select program_lifecycle('start',gen_random_uuid(),null,0,current_setting('e.version')::uuid,current_date,'UTC')$$,'P7701',null,'new enrollment RPC denied after expiration');
select lives_ok($$update favorite_workouts set name='Renamed after expiration',archived=true where id=current_setting('e.favorite')::uuid$$,'Favorite rename/removal remains owner management');
select lives_ok('select * from workout_history()','expired workout History remains available');
select lives_ok('select * from personal_records()','expired records remain available');

reset role;
set local role anon;
select throws_ok('select activate_account_trial()','42501',null,'anonymous activation denied');
select throws_ok('select account_access()','42501',null,'anonymous summary denied');
reset role;
select * from finish();
rollback;
